function adapt(input, solve, kit) {
  const [n] = input;
  const limit = 2 ** 30 - 1;
  // LeetCode exposes the question as a global API; the hidden number stays inside it.
  globalThis.commonSetBits = num => {
    if (!Number.isInteger(num) || num < 0 || num > limit) throw new Error(`commonSetBits(${num}) needs a whole number from 0 to 2^30 - 1.`);
    let shared = n & num;
    let count = 0;
    while (shared > 0) {
      count += shared & 1;
      shared >>= 1;
    }
    return count;
  };
  const result = solve();
  if (!Number.isInteger(result)) throw new Error('Return the hidden number as a whole number.');
  return result;
}

