function findNumber() {
  // Ask about all 30 bits at once, then leave out one bit at a time and see whether the count drops.
  const all = 2 ** 30 - 1;
  const total = commonSetBits(all);
  let n = 0;
  for (let i = 0; i < 30; i++) {
    if (commonSetBits(all - 2 ** i) < total) n += 2 ** i;
  }
  return n;
}

